    *namep = name = (char *)m->_packet + m->_len;
    ...
    do {
        if (moveBufp) {
            label = *bufp;
        }
        ...
        if (*label & 0xc0) {
            ...
            moveBufp = false;
            *bufp += 2;
        }
        ...
        memcpy(name, label + 1, labelLen);
        name[labelLen] = '.';
        name += labelLen + 1;

        if (moveBufp) {
            *bufp += labelLen + 1;
